def linha_produto(nome, preco):
    return f"{nome}: R$ {preco:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def linha_frete(valor):
    return "Frete: R$ " + f"{valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def linha_total(total):
    texto = f"{total:,.2f}"
    texto = texto.replace(",", "X").replace(".", ",").replace("X", ".")
    return "TOTAL: R$ " + texto

