import inspect

import relatorio


def test_funcao_existe():
    assert relatorio.formatar_moeda(1234.5) == 'R$ 1.234,50'
    assert relatorio.formatar_moeda(0) == 'R$ 0,00'


def test_saidas_iguais():
    assert relatorio.linha_produto('Caneta', 1234.5) == 'Caneta: R$ 1.234,50'
    assert relatorio.linha_frete(15) == 'Frete: R$ 15,00'
    assert relatorio.linha_total(1000000) == 'TOTAL: R$ 1.000.000,00'


def test_sem_duplicacao():
    for nome in ('linha_produto', 'linha_frete', 'linha_total'):
        fonte = inspect.getsource(getattr(relatorio, nome))
        assert 'formatar_moeda' in fonte and 'replace' not in fonte
